import React, { useState } from 'react';
import './Login.css'; // Reutiliza tu mismo CSS
import { useNavigate } from 'react-router-dom';

const Register = () => {
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage('');

    try {
      const response = await fetch('http://localhost:8080/registration/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ username, password })
      });

      if (response.ok) {
        setMessage('✅ Usuario registrado correctamente');
        setTimeout(() => navigate('/'), 2000); // redirige al login
      } else {
        const data = await response.json();
        setMessage(`❌ Error: ${data.message || 'No se pudo registrar'}`);
      }
    } catch (error) {
      console.error('Error:', error);
      setMessage('❌ Network error');
    }
  };

  return (
    <div className="login-page">
      <h1 className="login-title">CitaSaludEC</h1>
      <div className="login-container">
        <h2>Register</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button type="submit">Register</button>
        </form>
        {message && <p style={{ color: message.startsWith('✅') ? 'green' : 'red', marginTop: '1rem' }}>{message}</p>}
      </div>
    </div>
  );
};

export default Register;
